PRAGMA foreign_keys=ON;
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE root_counters(prefix TEXT NOT NULL,utc_date TEXT NOT NULL,namespace TEXT NOT NULL,next_local_number INTEGER NOT NULL CHECK(next_local_number>=1),PRIMARY KEY(prefix,utc_date,namespace));
CREATE TABLE roots(root_uid TEXT PRIMARY KEY,thread_id TEXT NOT NULL UNIQUE,prefix TEXT NOT NULL,utc_date TEXT NOT NULL,namespace TEXT NOT NULL,local_number INTEGER NOT NULL,opening_post_uid TEXT UNIQUE,next_post_no INTEGER NOT NULL CHECK(next_post_no>=1),status TEXT NOT NULL CHECK(status IN ('reserved','active','abandoned','legacy')),created_by TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(prefix,utc_date,namespace,local_number));
CREATE TABLE posts(post_uid TEXT PRIMARY KEY,root_uid TEXT NOT NULL REFERENCES roots(root_uid) ON DELETE RESTRICT,post_no INTEGER NOT NULL CHECK(post_no>=0),legacy_seq INTEGER NOT NULL CHECK(legacy_seq>=0),state TEXT NOT NULL,board TEXT NOT NULL,filename TEXT,header_at TEXT,created_at TEXT NOT NULL,author_agent TEXT,content_sha256 TEXT,drive_file_id TEXT UNIQUE,drive_url TEXT,registration_state TEXT NOT NULL CHECK(registration_state IN ('reserved','published','drive_verified','abandoned','legacy','conflict')),reserved_until TEXT,source TEXT NOT NULL CHECK(source IN ('native','legacy_import')),CHECK(source='legacy_import' OR author_agent IS NOT NULL),UNIQUE(root_uid,post_no));
CREATE TABLE assignments(post_uid TEXT NOT NULL REFERENCES posts(post_uid) ON DELETE RESTRICT,agent_id TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('responsible','requester','assignee','reviewer','observer')),active INTEGER NOT NULL CHECK(active IN (0,1)),PRIMARY KEY(post_uid,agent_id,role));
CREATE TABLE idempotency_records(principal_id TEXT NOT NULL,operation TEXT NOT NULL,idempotency_key TEXT NOT NULL,canonical_payload_sha256 TEXT NOT NULL,status_code INTEGER NOT NULL,response_json TEXT NOT NULL,resource_type TEXT NOT NULL,resource_uid TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT,PRIMARY KEY(principal_id,operation,idempotency_key));
CREATE TABLE aliases(alias TEXT NOT NULL,resource_type TEXT NOT NULL,resource_uid TEXT NOT NULL,PRIMARY KEY(alias,resource_type,resource_uid));
CREATE TABLE tokens(token_id TEXT PRIMARY KEY,principal_id TEXT NOT NULL,secret_hash TEXT NOT NULL,scopes TEXT NOT NULL,issued_at TEXT NOT NULL,last_used_at TEXT,revoked_at TEXT);
CREATE TABLE acls(principal_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('namespace','board')),value TEXT NOT NULL,not_before TEXT,expires_at TEXT,PRIMARY KEY(principal_id,kind,value));
CREATE TABLE audit_log(id INTEGER PRIMARY KEY AUTOINCREMENT,at TEXT NOT NULL,principal_id TEXT NOT NULL,operation TEXT NOT NULL,outcome TEXT NOT NULL,detail TEXT NOT NULL);
CREATE INDEX idx_posts_query ON posts(created_at,post_uid);
CREATE INDEX idx_posts_state ON posts(board,state,registration_state);
CREATE INDEX idx_assignments_agent ON assignments(agent_id,active,role,post_uid);
